#!/usr/bin/env python3
"""Repair the two lexical collisions in Arabic C2 Unit 06."""
from __future__ import annotations
import generate_arabic_c2_unit06 as base
base.SENSE.update({'مستفيد':'beneficiary','تأخير':'delay'})

p1=base.R[0]
p1['target_forms']=['ميزانية','مستفيد']
p1['text']=p1['text'].replace('قال رئيس المجلس إن الأولوية لا تعني بالضرورة أكبر مبلغ.', 'قال رئيس المجلس إن أكبر مستفيد من الخطة ليس بالضرورة صاحب أكبر بند، لأن بعض الخدمات تصل إلى مجموعات كثيرة بكلفة صغيرة.').replace('الأولوية الخطابية تصف قيمة، والأولوية التشغيلية تصف ترتيب الاختيارات تحت الندرة.', 'الخطاب يصف قيمة معلنة، أما التحليل التشغيلي فيسأل من يصبح مستفيدًا فعليًا من ترتيب الاختيارات تحت الندرة.')
p1['qa'][-2]=('single_word_definition','ما معنى «ميزانية»؟','خطة توزيع الموارد المالية على بنود خلال فترة معينة.','ميزانية')
p1['qa'][-1]=('single_word_definition','ما معنى «مستفيد»؟','شخص أو مجموعة تصل إليها منفعة من برنامج أو قرار أو مورد.','مستفيد')

p4=base.R[3]
p4['target_forms']=['تأخير','تناسب']
p4['text']=p4['text'].replace('ولتجنب صدمة مفاجئة قررت تنفيذًا تدريجيًا: تخفض الحصص المتاحة لكل مجموعة كل شهر.', 'ولتجنب صدمة مفاجئة قررت توزيع التنفيذ على أشهر. قال المدير إن هذا التأخير الجزئي في اكتمال القاعدة يجعلها أعدل.').replace('قالت المحللة إن التدريجي والتناسب ليسا الشيء نفسه. التدريج يصف توزيع التغيير عبر الزمن،', 'قالت المحللة إن تأخير اكتمال التنفيذ والتناسب ليسا الشيء نفسه. التأخير يصف توزيع التغيير عبر الزمن،').replace('هنا صار التنفيذ التدريجي أداة للتعلم لا حجة كافية على العدالة.', 'هنا صار تأخير اكتمال التنفيذ أداة للتعلم لا حجة كافية على العدالة.').replace('ويمكن أن يكشف التدرج أثرًا غير متوقع ثم يسمح بتعديل الخطة.', 'ويمكن أن يكشف التأخير المرحلي أثرًا غير متوقع ثم يسمح بتعديل الخطة.').replace('فإن تطبيقها ببطء لا يغير بنيتها؛', 'فإن تأخير تطبيقها الكامل لا يغير بنيتها؛')
p4['qa'][0]=('gist','لماذا لا يثبت تأخير اكتمال التنفيذ أن القاعدة متناسبة؟','لأن التأخير يصف الزمن، بينما التناسب يقارن العبء والهدف والبدائل.',None)
p4['qa'][4]=('main_claim','ما الفرق بين التأخير والتناسب؟','التأخير يغير توقيت اكتمال التنفيذ، والتناسب يختبر حجم العبء بالنسبة إلى الهدف والظروف.',None)
p4['qa'][-2]=('single_word_definition','ما معنى «تأخير» هنا؟','إرجاء جزء من التنفيذ أو إبطاء اكتماله إلى وقت لاحق.','تأخير')

p6=base.R[5]
replace={'أولوية':'مستفيد','تدريجي':'تأخير'}
p6['reviews']=[(replace.get(f,f),s,r) for f,s,r in p6['reviews']]
p6['text']=p6['text'].replace('قد تعلن أولوية لا تظهر بوضوح في الميزانية لأن القيود أو القرارات الهامشية تسير في اتجاه آخر.', 'قد تعلن قيمة لا يظهر مستفيدها الفعلي بوضوح في الميزانية لأن القيود أو القرارات الهامشية تسير في اتجاه آخر.').replace('أما التنفيذ التدريجي فيوزع التغيير على الزمن،', 'أما تأخير اكتمال التنفيذ فيوزع التغيير على الزمن،')
p6['qa'][7]=('summary','اذكر محاور الوحدة الخمسة.','الميزانية والمستفيدون، الأغلبية والإجراء، التفويض، التأخير والتناسب، والوفاق والحوافز.',None)

if __name__=='__main__':base.main()
